import{_ as a,o,c as t,a0 as i}from"./chunks/framework.D2qex3w9.js";const m=JSON.parse('{"title":"Order Routing Modal Specification","description":"","frontmatter":{},"headers":[],"relativePath":"specs/order-routing-modal/spec.md","filePath":"specs/order-routing-modal/spec.md"}'),r={name:"specs/order-routing-modal/spec.md"};function n(l,e,s,d,c,u){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="order-routing-modal-specification" tabindex="-1">Order Routing Modal Specification <a class="header-anchor" href="#order-routing-modal-specification" aria-label="Permalink to &quot;Order Routing Modal Specification&quot;">​</a></h1><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>Modal component for selecting order creation type and routing the user to the corresponding order form page.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><h3 id="requirement-modal-trigger" tabindex="-1">Requirement: Modal Trigger <a class="header-anchor" href="#requirement-modal-trigger" aria-label="Permalink to &quot;Requirement: Modal Trigger&quot;">​</a></h3><p>The parent component MUST open a <code>MatDialog</code> with <code>ModalCurrencyAddOrderComponent</code> when the add button is clicked.</p><h4 id="scenario-add-button-opens-modal" tabindex="-1">Scenario: Add button opens modal <a class="header-anchor" href="#scenario-add-button-opens-modal" aria-label="Permalink to &quot;Scenario: Add button opens modal&quot;">​</a></h4><ul><li>GIVEN the auction orders table is displayed</li><li>WHEN the user clicks the add button (<code>mat-mini-fab</code>)</li><li>THEN a <code>MatDialog</code> modal opens with <code>ModalCurrencyAddOrderComponent</code></li></ul><h3 id="requirement-order-type-selection" tabindex="-1">Requirement: Order Type Selection <a class="header-anchor" href="#requirement-order-type-selection" aria-label="Permalink to &quot;Requirement: Order Type Selection&quot;">​</a></h3><p>The modal MUST display a label &quot;Seleccione el tipo de orden que desea agregar:&quot; and a <code>&lt;mat-select&gt;</code> with exactly three options: Intervención, Mesa de cambio - Compra, Mesa de cambio - Venta.</p><h4 id="scenario-label-and-select-are-visible" tabindex="-1">Scenario: Label and select are visible <a class="header-anchor" href="#scenario-label-and-select-are-visible" aria-label="Permalink to &quot;Scenario: Label and select are visible&quot;">​</a></h4><ul><li>GIVEN the modal is open</li><li>WHEN the user views the modal content</li><li>THEN a descriptive label and a Material select with three order type options are displayed</li></ul><h3 id="requirement-route-navigation" tabindex="-1">Requirement: Route Navigation <a class="header-anchor" href="#requirement-route-navigation" aria-label="Permalink to &quot;Requirement: Route Navigation&quot;">​</a></h3><p>On option selection, the modal MUST navigate to the corresponding route and close itself.</p><table tabindex="0"><thead><tr><th>Option</th><th>Route</th></tr></thead><tbody><tr><td>Intervención</td><td><code>main/divisas/compra/intervencion</code></td></tr><tr><td>Mesa de cambio - Compra</td><td><code>main/divisas/compra/mesa-cambio</code></td></tr><tr><td>Mesa de cambio - Venta</td><td><code>main/divisas/venta/mesa-cambio</code></td></tr></tbody></table><h4 id="scenario-selection-navigates-and-closes" tabindex="-1">Scenario: Selection navigates and closes <a class="header-anchor" href="#scenario-selection-navigates-and-closes" aria-label="Permalink to &quot;Scenario: Selection navigates and closes&quot;">​</a></h4><ul><li>GIVEN the modal is open with the select</li><li>WHEN the user selects any option</li><li>THEN <code>this.router.navigate([route])</code> is called with the mapped route</li><li>AND the dialog closes</li></ul><h3 id="requirement-close-button" tabindex="-1">Requirement: Close Button <a class="header-anchor" href="#requirement-close-button" aria-label="Permalink to &quot;Requirement: Close Button&quot;">​</a></h3><p>The modal MUST include an SVG close button (X icon) using <code>--color-principal</code> for the icon color. The close button SHOULD display a hover lift animation.</p><h4 id="scenario-close-button-dismisses-modal" tabindex="-1">Scenario: Close button dismisses modal <a class="header-anchor" href="#scenario-close-button-dismisses-modal" aria-label="Permalink to &quot;Scenario: Close button dismisses modal&quot;">​</a></h4><ul><li>GIVEN the modal is open</li><li>WHEN the user clicks the SVG close button</li><li>THEN the dialog closes</li></ul><h3 id="requirement-visual-consistency" tabindex="-1">Requirement: Visual Consistency <a class="header-anchor" href="#requirement-visual-consistency" aria-label="Permalink to &quot;Requirement: Visual Consistency&quot;">​</a></h3><p>The modal MUST use CSS variables from <code>styles.scss</code> for all colors. No hardcoded hex or RGB values. The design MUST be minimal and visually coherent with the system theme.</p><h4 id="scenario-style-compliance" tabindex="-1">Scenario: Style compliance <a class="header-anchor" href="#scenario-style-compliance" aria-label="Permalink to &quot;Scenario: Style compliance&quot;">​</a></h4><ul><li>GIVEN the modal is rendered</li><li>THEN all color values reference CSS variables from <code>styles.scss</code></li></ul>',25)])])}const p=a(r,[["render",n]]);export{m as __pageData,p as default};
